const guard=$json;
const input=$('Receive Closing Context').item.json;

if(!guard.allowed){
  return {json:{
    status:guard.nextAction==='human_required'?'human_required':'blocked',
    guard,
    operations:[],
    reservation_guaranteed:false,
    blockers:[guard.reasonCode]
  }};
}

const operations=[{
  action:'TRANSITION_CUSTOMER_EVENT',
  customer_event_id:input.customer_event_id,
  from_stage:input.commercial_stage,
  to_stage:'FECHAMENTO',
  expected_version:input.stage_version,
  reason_code:input.trigger_type==='closing_form_callback'?'CLOSING_FORM_RECEIVED':'CUSTOMER_WANTS_TO_CLOSE',
  source_event_id:input.source_event_id ?? null
}];

const form=input.form_submission ?? null;
if(form && typeof form==='object'){
  const allowedFacts=[
    'customer_name','customer_email','customer_phone',
    'event_date','event_start_time','locality','event_type',
    'venue_name','venue_address','service_interest'
  ];
  for(const key of allowedFacts){
    const value=form[key];
    if(value===null || value===undefined || value==='') continue;
    operations.push({
      action:'RECORD_EVENT_FACT',
      customer_event_id:input.customer_event_id,
      fact_key:key,
      fact_value:value,
      fact_status:'known',
      source_type:'customer',
      source_ref:'closing_form',
      source_event_id:input.source_event_id ?? null
    });
  }
  operations.push({
    action:'EMIT_EVENT',
    event_type:'closing_form_received',
    customer_event_id:input.customer_event_id,
    idempotency_key:'closing-form:'+String(input.form_submission_id ?? input.source_event_id ?? input.customer_event_id)
  });
  operations.push({
    action:'UPSERT_MODULE_STATE',
    customer_event_id:input.customer_event_id,
    module_code:'contract',
    status:'in_progress',
    ready:false
  });
}else{
  operations.push({
    action:'PRESENT_CLOSING_FORM',
    customer_event_id:input.customer_event_id,
    form_url:'https://clickmais-microsite.lia-regis.chatgpt.site'
  });
  operations.push({
    action:'EMIT_EVENT',
    event_type:'customer_wants_to_close',
    customer_event_id:input.customer_event_id
  });
}

return {json:{
  status:'planned',
  guard,
  operations,
  reservation_guaranteed:false,
  availability_claim:'preliminary',
  blockers:[]
}};
